// th18_s6_mb1: TH18 v1.00a Stage 6 midboss MBoss / MBoss1 / MBoss1_at.
// Source: st06mbs.ecl.txt:6-126 (created at st06.ecl.txt:1531).
// Source t0 (M:13 timerReset) starts after the 120-frame target opening buffer.
const TIME_LIMIT: int = 1440;   // 120 buffer + source slot-1 timer 1320
const SOURCE_LIMIT: int = 1320;
const OPENING_BUFFER: int = 120;
const TH18_KUNAI: int = 496;   // source type9, base radius 2.4

// --- moveRand helper (M:51/54), adapted from the checked TH18 412 recipe ---
// Source moveLimit(0,128,280,256): final x[-140,140], y[0,256]; the direction
// window is x[-70,70], y[64,192]. moveRand(200,0,0.3): speed 0.3*(1-k/200).
// int slot0 = next source movement tick; fx0/fx1 = saved logical cos/sin.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    if k > 200 { return; }
    var speed: fx = 0fx;
    if k < 200 { speed = ((200-k) as fx) * 0.3fx / 200fx; }
    var nx: fx = $self_x + self_fx(0)*speed;
    var ny: fx = $self_y + self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 0fx { ny = 0fx; }
    if ny > 256fx { ny = 256fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 0x405b90 signed unit random * pi, kept as unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source normalizes only this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 64fx {
        if a < 0 { a = -a; }
    } else if $self_y > 192fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad = 522 BAM.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// Source etAim mode1 fixed fan: offsets F(N,i) = (-1)^i*floor-scaled spacing.
// (alpha, delta, N) are the fired etAngle values; spawn point is the etOffsetRad
// point, identical for the whole fan.
sub card_fan(alpha: angle, delta: int, n: int, color: int, speed: fx, ox: fx, oy: fx) {
    var base: int = alpha as int;
    for i in 0..n {
        var off: int = 0;
        if n%2 == 1 {
            off = ((i+1)/2)*delta;
        } else {
            off = (i/2)*delta + delta/2;
        }
        if i%2 != 0 { off = -off; }
        _ = fire(TH18_KUNAI, color, ox, oy, speed, (base+off) as angle, none, none);
    }
}

// M:62-126 MBoss1_at. a_total is the source argument A.
// floatTime(0,E,360,1,0,A): mode1 is t^2, so E(j)=A*(j*W/360)^2, held at A
// after 360 frames. rot is the cumulative B+-E / C-+E rotation before volley k.
sub mboss1_at(a_total: angle) {
    var rank: int = global(GVAR_RANK);
    var wp: int = 12;
    if rank == 0 { wp = 24; }
    var n: int = 3;
    if rank == 0 { n = 1; }
    if rank == 2 { n = 4; }
    if rank == 3 { n = 5; }
    var b0: angle = atan2($player_y-$self_y, $player_x-$self_x);
    var d0: angle = b0 - 180deg;   // %D = ANGLE_PLAYER - pi, fixed per call
    var bam0: int = b0 as int;
    var a_bam: int = a_total as int;
    var rot: int = 0;
    for k in 0..30 {
        var b: angle = (bam0+rot) as angle;   // %B
        var c: angle = (bam0-rot) as angle;   // %C
        // M:95/98/101/104 etOffsetRad(B+-pi/2, 70).
        var oxl: fx = $self_x + 70fx*cos(b - 90deg);
        var oyl: fx = $self_y + 70fx*sin(b - 90deg);
        var oxr: fx = $self_x + 70fx*cos(b + 90deg);
        var oyr: fx = $self_y + 70fx*sin(b + 90deg);
        // M:96-105: et0 fan centered B/C, spacing 0.17453292; et1 fan centered D,
        // spacing 0.3228859 (18.5deg). Configure-time 32/20deg are overwritten.
        card_fan(b, a_bam, n, 2, 2.7fx, oxl, oyl);
        card_fan(c, a_bam, n, 2, 2.7fx, oxr, oyr);
        card_fan(d0, 3367, 17, 4, 4.0fx, oxl, oyl);
        card_fan(d0, 3367, 17, 4, 4.0fx, oxr, oyr);
        card_wait(wp);                 // M:115 wait([-1]) rank split
        var j: int = k+1;              // E update after this volley
        var e: int = 0;
        if rank == 0 {
            if j <= 15 { e = a_bam*j*j/225; } else { e = a_bam; }
        } else {
            e = a_bam*j*j/900;
        }
        rot = rot + e;
        if rank == 0 { rot = rot + e; }  // M:118-120 extra Easy B/C step
    }
}

// M:45-60 MBoss1: each entry is a synchronous fire helper containing waits.
sub mboss1() {
    loop {
        if $frame >= self_int(1) { return; }
        card_move_rand();              // M:51
        mboss1_at(10deg);              // M:52
        card_wait(30);                 // M:53
        if $frame >= self_int(1) { return; }
        card_move_rand();              // M:54
        mboss1_at(10deg);              // M:55
        card_wait(30);                 // M:56
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    set_self_int(1, $frame + SOURCE_LIMIT);
    // M:28-30: spawn/entry position is (-192,-64); the 100-frame quad-out move
    // overlaps the following wait(40) in source.
    move_to(100, 0fx, 128fx, EASE_QUAD_OUT);
    wait(40);
    // M:31 moveLimit is folded into card_arm_next_step limits.
    // M:32/35 dialogWait, M:33 EffChargePoint3 and M:14 Ecl_EtBreak_ni are
    // dialogue/presentation/cleanup only (solo card starts clean).
    mboss1();
}

async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    loop { wait(1); }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(20fx);   // source setHitbox(40,40): ordinary circle uses width*0.5
    set_hurtbox(24fx);  // source setHurtbox(48,48): damage circle uses width*0.5
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    // Extra control enemy at the origin, body collision off; real enemy keeps
    // the source body/hurt boxes above.
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    // Source S:1531 creates at (-192,-32); M:28 writes (-192,-64) before any
    // movement/emission, so the card starts at that effective entry point.
    _ = spawn_enemy(-192fx, -64fx, 14000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
